// Parse Zalo OA webhook data
const body = $input.first().json.body;
const eventName = body.event_name || 'unknown';
const msg = body.message || {};

// Get sender info
let userId = '';
let userName = '';
let userAvatar = '';

if (body.sender && body.sender.id) {
  userId = body.sender.id;
  userName = body.sender.name || '';
}

// Parse message type and content
let messageType = 'text';
let messageText = '';
let mediaUrl = '';

if (eventName === 'user_send_text') {
  messageType = 'text';
  messageText = msg.text || '';
} else if (eventName === 'user_send_image') {
  messageType = 'image';
  messageText = '[Hinh anh]';
  if (msg.attachments && msg.attachments[0] && msg.attachments[0].payload) {
    mediaUrl = msg.attachments[0].payload.url || '';
  }
} else if (eventName === 'user_send_file') {
  messageType = 'file';
  messageText = '[File]';
  if (msg.attachments && msg.attachments[0] && msg.attachments[0].payload) {
    mediaUrl = msg.attachments[0].payload.url || '';
  }
} else if (eventName === 'user_send_link') {
  messageType = 'link';
  messageText = msg.text || '[Link]';
} else if (eventName === 'user_send_sticker') {
  messageType = 'sticker';
  messageText = '[Sticker]';
} else if (eventName === 'user_send_location') {
  messageType = 'location';
  messageText = msg.text || '[Vi tri]';
} else if (eventName === 'follow') {
  messageType = 'system';
  messageText = 'Nguoi dung da theo doi OA';
} else if (eventName === 'unfollow') {
  messageType = 'system';
  messageText = 'Nguoi dung da bo theo doi OA';
} else {
  messageText = msg.text || JSON.stringify(msg);
}

return {
  json: {
    event: eventName,
    userId: userId,
    userName: userName,
    userAvatar: userAvatar,
    messageType: messageType,
    message: messageText,
    mediaUrl: mediaUrl,
    msgId: msg.msg_id || ''
  }
};

// Lay thong tin user tu Zalo API response
const zaloResponse = $input.first().json;
const webhookData = $('Parse Webhook').first().json;

// Check for Zalo API error
if (zaloResponse.error && zaloResponse.error !== 0) {
  // Khong lay duoc thong tin user, van tiep tuc
  return {
    json: {
      ...webhookData,
      userName: webhookData.userName || 'Khach hang Zalo',
      userAvatar: ''
    }
  };
}

// Extract user info from Zalo API response
const userName = zaloResponse.name || webhookData.userName || 'Khach hang Zalo';
const userAvatar = (zaloResponse.picture && zaloResponse.picture.data && zaloResponse.picture.data.url) 
  ? zaloResponse.picture.data.url 
  : '';

return {
  json: {
    ...webhookData,
    userName: userName,
    userAvatar: userAvatar
  }
};

// Get MTL App URL from environment
const appUrl = $env.MTL_APP_URL || 'http://localhost:5000';
const webhookData = $('Set User Info').first().json;

return {
  json: {
    ...webhookData,
    appUrl: appUrl
  }
};
